sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // final_value is the resolved truth for this field:
    //   override_value -> manual_value -> mapped_value -> extracted_value
    //
    // The chain is NOT re-implemented here. ExtractionApplier.getFinalValue is
    // the single definition of it; copying those four lines into a rule is
    // exactly how the list column and the applier drift apart, and the drift is
    // silent - the grid shows one value while a different one is written to the
    // system of record.
    //
    // Runs BEFORE the write, so the column is correct in the same transaction
    // as the edit that caused it. No second update(), no recursion, and no
    // async gap in which a reader could see the old value.
    //
    // Insert included on purpose: a row loaded from the seed file, created by
    // ExtractionMapper or posted through the API all resolve the same way.
    var resolved = new ExtractionApplier().getFinalValue(current);

    // final_value is 1000 chars, extracted_value and mapped_value are 2000 -
    // truncate rather than let a long value fail the write
    current.setValue('final_value', String(resolved || '').substring(0, 1000));

})(current, previous);
